import {readFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {createHash} from 'node:crypto';
const root=resolve('NeuralSkills/roles/saas/backend-engineering');
const hash=b=>createHash('sha256').update(b).digest('hex');
const record=JSON.parse(await readFile(resolve(root,'evals/evidence/snapshot-context-repair.json'),'utf8'));
const originals=[];for(const f of record.originalSnapshots){const actual=hash(await readFile(resolve(root,f.path)));originals.push({path:f.path,matchesBefore:actual===f.before,matchesAfter:actual===f.after});}
const added=[];for(const f of record.added){const bytes=await readFile(resolve(root,f.path));added.push({path:f.path,kind:f.kind,matchesRecorded:hash(bytes)===f.sha256,...(f.kind==='byte-identical canonical resource copy'?{matchesCanonical:bytes.equals(await readFile(resolve(root,f.canonical)))}:{explicitPostTrialMarker:bytes.toString('utf8').includes('after trial completion')&&bytes.toString('utf8').includes('not an input inspected by the trial agent')})});}
const result={observedAt:new Date().toISOString(),originalSnapshotCount:originals.length,originalSnapshotIssues:originals.filter(x=>!x.matchesBefore||!x.matchesAfter),companionCount:added.length,companionIssues:added.filter(x=>!x.matchesRecorded||x.matchesCanonical===false||x.explicitPostTrialMarker===false),rawResultHashMatches:hash(await readFile(resolve(root,'evals/trials/B01-skill-2/result.json')))===record.rawResultUnchangedSha256};
console.log(JSON.stringify(result,null,2));
